private void pop(String descriptor){
	 if ("void".contentEquals(descriptor)){
		return;
	 }
	 int popCount = 0;
	 String descriptorElem = null;
	 while ((descriptorElem = getOutputFrameStack().pop()) != null) {
		 if (descriptorElem.equals(descriptor)) {
			 break;
		 } else if (Descriptor.isNonVoidReturnType(descriptorElem)) {
			 popCount++;
		 }
	 }
	 if (popCount > 0) {
		 getOutputFrameStack().pop(popCount - 1);
	 }
 }

