public static <T> Converter lookup(final Class<T> clazz) {
    // Check if there is a registered converter for the specific class
    Converter<T> converter = registeredConverters.get(clazz);

    if (converter == null) {
        // Check if there is a registered converter for the superclass or interfaces
        Class<? super T> superclass = clazz.getSuperclass();
        while (converter == null && superclass != null) {
            converter = registeredConverters.get(superclass);
            if (converter != null) { break; }

            for (Class<?> iface : clazz.getInterfaces()) {
                converter = registeredConverters.get(iface);
                if (converter != null) { break; }
            }

            superclass = superclass.getSuperclass();
        }
    }

    return converter;
}

