public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Initialize the list of path segments
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Get the path component of the URI
    String path = u.getPath();

    // Remove the leading '/' from the path if it is an absolute path
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    // Extract the path segments from the path
    String[] segments = path.split("/");

    // Loop through each path segment and create a new PathSegmentImpl object
    for (String segment : segments) {
        PathSegmentImpl pathSegment = new PathSegmentImpl(segment);
        if (decode) {
            pathSegment.setParameter(PathSegment.URLEncoded, true);
        }
        pathSegments.add(pathSegment);
    }

    // Return the list of path segments
    return pathSegments;
}

