    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] argumentClasses = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        if (actualTypeArgument instanceof Class) {
            argumentClasses[i] = (Class<?>) actualTypeArgument;
        } else if (actualTypeArgument instanceof ParameterizedType) {
            argumentClasses[i] = resolveArguments(actualTypeArgument, targetType);
        } else {
            throw new IllegalArgumentException("Unsupported type: " + actualTypeArgument);
        }
    }
    return argumentClasses;
}

