protected void append(LoggingEvent event){

	// If there are no clients connected, return without doing anything
	if (clientList.size() == 0){
		return;
	}

	// Get the message and convert it to a string
	String message = event.getRenderedMessage();

	// Iterate over the connected clients and write the message to each one
	for (WebSocket client : clientList){
		try{
			// Write the message to the client's output stream
			client.getSession().getRemote().sendString(message);
		}catch (WebSocketException e){
			// If an error occurs while writing to the client, remove them from the list of connected clients
			clientList.remove(client);
		}
	}
}

