public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        return Collections.emptyList();
    }
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse line into String values
            String[] values = line.split("\\s+");
            if (values.length == 3) {
                long startTime = Long.parseLong(values[0]);
                long duration = Long.parseLong(values[1]);
                String threadName = values[2];
                // Check if thread is in time range
                if (timeRanges.stream().anyMatch(range -> range.contains(startTime, duration))) {
                    // Create new ThreadSnapshot object
                    ThreadSnapshot snapshot = new ThreadSnapshot(startTime, duration, threadName);
                    snapshots.add(snapshot);
                }
            }
        }
    }
    return snapshots;
}

