public static int nextPrime(int desiredCapacity) {

	// Handle easy cases
	if (desiredCapacity <= 0) {
		return 1;
	} else if (desiredCapacity <= 10) {
		return desiredCapacity;
	}

	// Handle edge cases closely related to 1000
	if (desiredCapacity >= 1000) {
		int result = nextPrime(999);
		return result + 2;
	}

	// Handle cases around 1000
	int result = nextPrime(990);
	if (result >= desiredCapacity) {
		return result;
	}

	// Handle remaining cases
	while (true) {
		result += 2;
		if (result >= desiredCapacity) {
			return result;
		}
		if (isPrime(result)) {
			return result;
		}
	}
}

