public long readRawVarint64() throws IOException {
  byte temp = input_.readRawByte();
  if (temp <= 0x7f) {
    return temp;
  }
  int result = temp & 0x7f;
  if ((temp = input_.readRawByte()) >= 0) {
    result |= (temp << 7);
  } else {
    result |= ((temp & 0x7f) << 7);
    if ((temp = input_.readRawByte()) >= 0) {
      result |= (temp << 14);
    } else {
      result |= ((temp & 0x7f) << 14);
      if ((temp = input_.readRawByte()) >= 0) {
        result |= (temp << 21);
      } else {
        result |= ((temp & 0x7f) << 21);
        result |= (input_.readRawByte() << 28);
        if (result < 0) {
          // Discard upper 32 bits.
          for (int i = 0; i < 5; i++) {
            if (input_.readRawByte() >= 0) {
              return result;
            }
          }
          throw InvalidProtocolBufferException.invalidVarInt();
        }
      }
    }
  }
  return result;
}

