public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int contentSize = 0;
    // Write contents of the buffer into the output stream
    while (node != null) {
        // Write the data for the current node
        out.writeInt(node.getData().length);
        out.write(node.getData());
        // Update the content size
        contentSize += node.getData().length;
        // Move to the next node
        node = node.next;
    }
    return contentSize;
}

